                                            referer = it2[1].replace(/；；/g, ";");
                                        }
                                        if (it2[0] == "User-Agent") {
                                            ua = it2[1].replace(/；；/g, ";");
                                        }
                                        if (it2[0] == "Cookie") {
                                            cookie0 = it2[1].replace(/；；/g, ";");
                                        }
                                    }
